import{_ as d,o as e,c as a,a2 as o}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"1. 连接与快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"connection.md","filePath":"connection.md"}'),r={name:"connection.md"};function c(n,t,l,i,s,h){return e(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="_1-连接与快速开始" tabindex="-1">1. 连接与快速开始 <a class="header-anchor" href="#_1-连接与快速开始" aria-label="Permalink to &quot;1. 连接与快速开始&quot;">​</a></h1><h2 id="_1-1-服务器地址" tabindex="-1">1.1 服务器地址 <a class="header-anchor" href="#_1-1-服务器地址" aria-label="Permalink to &quot;1.1 服务器地址&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>Java 版地址</td><td><code>pepper.ltd:25565</code></td></tr><tr><td>基岩版地址</td><td><code>pepper.ltd:19132</code></td></tr><tr><td>Java 版认证</td><td>仅正版账号</td></tr><tr><td>基岩版认证</td><td>无需 Java 账号，用 Xbox Live 账号直接进入</td></tr><tr><td>服务器版本</td><td>26.3</td></tr><tr><td>客户端版本</td><td>建议使用较新的 1.21+ 客户端；过旧的版本可能无法进入</td></tr></tbody></table><p>Java 版和基岩版进入的是同一个服务器，聊天、经济、领地、联盟数据互通。</p><h2 id="_1-2-第一次进入建议流程" tabindex="-1">1.2 第一次进入建议流程 <a class="header-anchor" href="#_1-2-第一次进入建议流程" aria-label="Permalink to &quot;1.2 第一次进入建议流程&quot;">​</a></h2><ol><li>进入后先输入 <code>/spawn</code>，确认自己在主城。</li><li>在主城输入 <code>/ej</code>，5 秒后会被弹射到主世界随机落点。主城全境不能圈地，所以<strong>先离开主城</strong>；另外每个世界的出生点 100 格内也不能完整圈地。</li><li>落地后手持普通金锄，<strong>左键</strong>点第一个角、<strong>右键</strong>点对角，再输入 <code>/pclaim create &lt;领地名&gt;</code>，圈一块个人领地（免费，消耗领地额度）。</li><li>用 <code>/sethome home</code> 设一个个人传送点；再用 <code>/pclaim settp</code> 给领地设一个领地传送点。</li><li>挖到的钻石可以放进银行：<code>/bank add &lt;数量&gt;</code>，避免随身携带。</li><li>迷路或卡住：<code>/spawn</code> 回主城，<code>/back</code> 回上一个位置或死亡点。</li></ol><h2 id="_1-3-主城与世界" tabindex="-1">1.3 主城与世界 <a class="header-anchor" href="#_1-3-主城与世界" aria-label="Permalink to &quot;1.3 主城与世界&quot;">​</a></h2><table tabindex="0"><thead><tr><th>世界</th><th>说明</th></tr></thead><tbody><tr><td>主城</td><td>独立的主城区域，下方是虚空；和平难度，禁止 PvP</td></tr><tr><td>主世界</td><td>主要生存世界，难度困难；世界边界 100,000 格宽</td></tr><tr><td>下界</td><td>可通过传送门进入</td></tr><tr><td>末地</td><td>可通过末地传送门进入</td></tr></tbody></table><p>主城<strong>全境不能创建领地</strong>；此外每个世界的出生点 <strong>100 格内不能完整圈地</strong>。主城可用 <code>/warp court</code> 前往观景台，用 <code>/spawn</code> 回出生点。</p>',9)])])}const b=d(r,[["render",c]]);export{p as __pageData,b as default};
